/// <summary>
/// CB705_VendorRebatesPosting
/// </summary>
[ExtensionOf(classStr(TAMRebateDatePeriod))]
final class METTAMRebateDatePeriod_Extension
{
    private METInvoiceConsolidationByRebateType consolidationByRebateType;
    private METVendorRebateTypeId               vendorRebateTypeId;
    private TAMRebateParameters                 rebateParameters; 
    private TAMRebateTransactionType            transactionType;

}

Method.Source:
/// <summary>
/// Parm method for the rebate transaction type
/// </summary>
/// <param name = "_transactionType"><c>TAMRebateTransactionType</c></param>
/// <returns><c>TAMRebateTransactionType</c></returns>
public TAMRebateTransactionType metParmRebateTransactionType(TAMRebateTransactionType _transactionType = transactionType)
{
    transactionType = _transactionType;
    return transactionType;
}

/// <summary>
/// Initialise vendorRebateTypeId and consolidationByRebateType
/// </summary>
/// <param name = "_rebateDate">Rebate date</param>
/// <param name = "_rebatePerFieldId">Rebate per field id</param>
/// <param name = "_periodTypeIdFieldId">Period typeId fieldId</param>
protected void initializeFromRebateDate(TAMRebateDate _rebateDate, FieldId _rebatePerFieldId, FieldId _periodTypeIdFieldId)
{
    next initializeFromRebateDate(_rebateDate, _rebatePerFieldId, _periodTypeIdFieldId);

    rebateParameters = TAMRebateParameters::find();

    TAMRebateTable rebateTable = TAMRebateTable::find(_rebateDate.RebateId);
    vendorRebateTypeId = rebateTable.METVendRebateTypeId;

    TAMRebateDeal rebateDeal = TAMRebateDeal::find(rebateTable.RebateDeal);
    consolidationByRebateType = rebateDeal.METInvoiceConsolidationByRebateType;
}

/// <summary>
/// Adding vendorRebateTypeId in the mapKey
/// </summary>
/// <param name = "_fromDate">From date</param>
/// <param name = "_toDate">To date</param>
/// <param name = "_rebateRefId">Rebate ref id</param>
/// <returns>mapKey container</returns>
protected container getRebateTransIdMapKey(FromDate _fromDate, ToDate _toDate, TAMRebateRefId _rebateRefId)
{
    container con = next getRebateTransIdMapKey(_fromDate, _toDate, _rebateRefId);

    if (transactionType ==TAMRebateTransactionType::Rebate
    &&  rebateParameters.METProcessVendRebateBasedVendRebType
    &&  consolidationByRebateType)
    {
        return [_fromDate, _toDate, vendorRebateTypeId];
    }

    return con;
}

/// <summary>
/// CB705_VendorRebatePosting moving extension now that method is public
/// When an instance of TAMRebateDatePeriod is created, this method will set the TAMRebateTransactionType
/// So we can update the RebateTransIdMapKey to add vendorRebateTypeId only in the rebate transaction type scenario TAMRebateDatePeriod\getRebateTransIdMapKey.
/// </summary>
/// <param name = "_instance">Instance of <c>TAMRebateDatePeriod</c></param>
/// <param name = "_transactionType">Rebate transaction type</param>
/// <returns>Instance of <c>TAMRebateDatePeriod</c> set with the TAMRebateTransactionType</returns>
public static TAMRebateDatePeriod newFromRebateDateAndTransactionType(TAMRebateDate _rebateDate, TAMRebateTransactionType _transactionType)
{
    TAMRebateDatePeriod rebateDatePeriod = next newFromRebateDateAndTransactionType(_rebateDate, _transactionType);
    rebateDatePeriod.metParmRebateTransactionType(_transactionType);

    return rebateDatePeriod;
}
